-- Script para poblar directamente las tablas normalizadas tipo_pokemon y pokemon.
-- Este script es autónomo y no depende de la tabla pokemon_tipo_raw.

CREATE SCHEMA IF NOT EXISTS `pokemondb`;
USE `pokemondb`;

DROP TABLE IF EXISTS pokemon;
DROP TABLE IF EXISTS tipo_pokemon;

CREATE TABLE tipo_pokemon (
    id_tipo INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE pokemon (
    id_pokemon INT AUTO_INCREMENT PRIMARY KEY,
    fid_tipo INT NOT NULL,
    nombre VARCHAR(80) NOT NULL,
    altura DECIMAL(5,2),
    peso DECIMAL(5,2),
    estado_evolutivo ENUM('BASICO','INTERMEDIO','FINAL') NOT NULL,
    descripcion VARCHAR(255),
    imagen_url VARCHAR(255),
    FOREIGN KEY (fid_tipo) REFERENCES tipo_pokemon(id_tipo)
);



-- Consultas de prueba
SELECT COUNT(*) AS total_tipos FROM tipo_pokemon;
SELECT COUNT(*) AS total_pokemon FROM pokemon;

-- Procedimiento almacenado para obtener el total de pokémones (se usa procedimiento para evitar el error 1419 en servidores con binary logging activo y sin privilegios SUPER)
DROP PROCEDURE IF EXISTS obtener_total_pokemon;
DELIMITER //
CREATE PROCEDURE obtener_total_pokemon()
BEGIN
    SELECT COUNT(*) AS total FROM pokemon;
END //
DELIMITER ;

-- Procedimiento almacenado para obtener un pokémon por índice de 0 (id_pokemon - 1)
DROP PROCEDURE IF EXISTS obtener_pokemon_por_indice;
DELIMITER //
CREATE PROCEDURE obtener_pokemon_por_indice(IN p_indice INT)
BEGIN
    SELECT 
        p.id_pokemon AS id,
        p.nombre AS Nombre,
        p.altura AS Altura,
        p.peso AS Peso,
        p.estado_evolutivo AS EstadoEvolutivo,
        t.nombre AS Tipo,
        p.descripcion AS Descripcion,
        p.imagen_url AS ImagenUrl
    FROM pokemon p
    INNER JOIN tipo_pokemon t ON p.fid_tipo = t.id_tipo
    WHERE p.id_pokemon = p_indice + 1;
END //
DELIMITER ;

-- Pruebas de los procedimientos
CALL obtener_total_pokemon();
CALL obtener_pokemon_por_indice(0);
CALL obtener_pokemon_por_indice(24);